# Analyze the 5s in the demo to see how they form structures
input_demo = [
    [5, 0, 0, 5, 0],
    [5, 0, 0, 5, 0],
    [5, 0, 5, 5, 5],
    [5, 5, 5, 0, 0],
    [0, 0, 5, 0, 0],
    [0, 0, 5, 5, 5],
    [0, 0, 0, 5, 0],
    [5, 5, 5, 5, 0],
    [0, 5, 0, 0, 0],
    [0, 5, 0, 0, 0],
    [0, 5, 5, 5, 0],
    [0, 0, 0, 5, 0],
    [0, 5, 5, 5, 5],
    [5, 5, 0, 0, 0],
    [0, 5, 0, 0, 0],
]

h, w = 15, 5

def find_component_of_5s(grid, start_pos):
    visited = set()
    stack = [start_pos]
    while stack:
        i, j = stack.pop()
        if (i, j) in visited or grid[i][j] != 5:
            continue
        visited.add((i, j))
        for di, dj in [(0,1), (0,-1), (1,0), (-1,0)]:
            ni, nj = i + di, j + dj
            if 0 <= ni < h and 0 <= nj < w and grid[ni][nj] == 5 and (ni, nj) not in visited:
                stack.append((ni, nj))
    return frozenset(visited)

# Find connected components of 5s
five_components = {}
for i in range(h):
    for j in range(w):
        if input_demo[i][j] == 5:
            comp = find_component_of_5s(input_demo, (i,j))
            if comp not in five_components:
                five_components[comp] = []
            five_components[comp].append((i,j))

print("Number of 5-components:", len(five_components))
for comp_id, cells in sorted(five_components.items(), key=lambda x: -len(x[1])):
    print(f"Size {len(cells)}: {sorted(cells)[:5]}...")

# Now let's think about "holes" - 0 cells completely surrounded by a single 5-component
def is_surrounded_by_comp(grid, zero_cell, five_comp):
    """Check if this zero cell would be enclosed by five_comp"""
    # Flood fill from zero_cell without passing through five_comp OR any OTHER 5s
    # If the zero connects to an edge, it's NOT surrounded
    visited = set()
    stack = [zero_cell]

    while stack:
        i, j = stack.pop()
        if (i, j) in visited or i < 0 or i >= h or j < 0 or j >= w:
            continue
        if (i, j) == zero_cell:
            visited.add((i, j))
            continue
        if grid[i][j] == 5 and (i, j) not in five_comp:
            # Hit a 5 that's not part of our component - can't go through
            # But we should have hit the boundary already
            continue
        visited.add((i, j))
        for di, dj in [(0,1), (0,-1), (1,0), (-1,0)]:
            ni, nj = i + di, j + dj
            if (ni, nj) not in visited and 0 <= ni < h and 0 <= nj < w and grid[ni][nj] != 5:
                stack.append((ni, nj))

    # If we reached an edge without hitting obstacles, not surrounded
    for i, j in visited:
        if i == 0 or i == h-1 or j == 0 or j == w-1:
            return False

    return True

# Hmm, actually let me think differently. 
# What if the rule is: find the largest 5-component that "surrounds" some area, then fill that area with 8s?
print("\n--- Checking which 5-components surround holes ---")

for comp_cells, label in sorted(five_components.items(), key=lambda x: -len(x[1])):
    # Count zero cells adjacent to this component
    adj_zeros = set()
    for ci, cj in comp_cells:
        for di, dj in [(0,1), (0,-1), (1,0), (-1,0)]:
            ni, nj = ci + di, cj + dj
            if 0 <= ni < h and 0 <= nj < w and input_demo[ni][nj] == 0:
                adj_zeros.add((ni, nj))

    # How many unique zeros?
    print(f"Component size {len(comp_cells)}: touches {len(adj_zeros)} different zero-cells")
    print(f"  Sample zeros: {sorted(list(adj_zeros))[:5]}...")
